async function loadSalesModule(){if(!activeBusinessId)return;message("globalMessage","جارٍ تحميل العملاء وفواتير المبيعات...");const [cr,ir]=await Promise.all([client.from("parties").select("id,name,company,phone,customer_type,kind").eq("business_id",activeBusinessId).in("kind",["customer","both"]).order("name"),client.from("sales_invoices").select("id,invoice_no,customer_id,customer_name_snapshot,invoice_date,subtotal,discount,total,paid_total,due_total,status,business_name_snapshot,business_phone_snapshot,business_address_snapshot,notes").eq("business_id",activeBusinessId).neq("status","void").order("invoice_date",{ascending:false}).limit(250)]);if(cr.error)return fail(cr.error);if(ir.error)return fail(ir.error);customers=cr.data||[];salesInvoices=ir.data||[];renderCustomers();fillSaleCustomers();renderSalesInvoices();await loadSalesReturns();message("globalMessage","");}
async function saveCustomer(e){e.preventDefault();if(!permission("parties.create"))return;const f=new FormData(e.currentTarget),payload={business_id:activeBusinessId,kind:"customer",name:String(f.get("name")).trim(),company:String(f.get("company")||"").trim()||null,phone:String(f.get("phone")||"").trim()||null,customer_type:f.get("customer_type"),address:String(f.get("address")||"").trim()||null,notes:String(f.get("notes")||"").trim()||null};message("globalMessage","جارٍ حفظ العميل...");const {error}=await client.from("parties").insert(payload);if(error)return fail(error);e.currentTarget.reset();show("customerEditor",false);await loadSalesModule();message("globalMessage","تم حفظ العميل.");}
async function renderCustomers(){if(!permission("parties.view"))return;const {data,error}=await client.from("party_account_balances").select("party_id,sales_total,customer_payments,returns_total,customer_net_balance").eq("business_id",activeBusinessId);if(error)return fail(error);const bmap=Object.fromEntries((data||[]).map(x=>[x.party_id,x]));$("customersRows").innerHTML=customers.map(c=>{const b=bmap[c.id]||{};return '<tr><td><strong>'+esc(c.name)+'</strong><small>'+esc(c.company||"")+'</small></td><td>'+ (c.customer_type==="wholesale"?"جملة":"قطاعي")+'</td><td>'+esc(c.phone||"—")+'</td><td>'+money(b.sales_total)+'</td><td>'+money(b.customer_payments)+'</td><td>'+money(b.customer_net_balance)+'</td><td><button class="tiny secondary" data-cstatement="'+c.id+'">عرض</button></td></tr>';}).join("")||'<tr><td colspan="7">لا يوجد عملاء مسجلون.</td></tr>';$("customersRows").querySelectorAll("[data-cstatement]").forEach(b=>b.addEventListener("click",()=>loadCustomerStatement(customers.find(c=>c.id===b.dataset.cstatement))));}
async function loadCustomerStatement(c){if(!c||!permission("parties.view"))return;const [br,sr]=await Promise.all([client.from("party_account_balances").select("sales_total,customer_payments,returns_total,customer_net_balance").eq("business_id",activeBusinessId).eq("party_id",c.id).maybeSingle(),client.from("party_account_statement").select("entry_type,reference_no,entry_date,debit,credit,description").eq("business_id",activeBusinessId).eq("party_id",c.id).order("entry_date",{ascending:true})]);if(br.error)return fail(br.error);if(sr.error)return fail(sr.error);$("customerStatementTitle").textContent="كشف حساب: "+c.name;$("customerStatementBalance").textContent="إجمالي المبيعات: "+money(br.data?.sales_total)+" · المتحصل: "+money(br.data?.customer_payments)+" · المرتجعات: "+money(br.data?.returns_total)+" · المستحق: "+money(br.data?.customer_net_balance);const labels={opening_balance:"رصيد افتتاحي",sale_invoice:"فاتورة مبيعات",payment:"تحصيل",sales_return:"مرتجع مبيعات"};$("customerStatementRows").innerHTML=(sr.data||[]).map(x=>'<tr><td>'+esc(x.entry_date)+'</td><td>'+esc(labels[x.entry_type]||x.entry_type)+'</td><td>'+esc(x.reference_no||"—")+'</td><td>'+money(x.debit)+'</td><td>'+money(x.credit)+'</td><td>'+esc(x.description||"")+'</td></tr>').join("")||'<tr><td colspan="6">لا توجد حركات حساب.</td></tr>';show("customerStatement",true);$("customerStatement").scrollIntoView({behavior:"smooth",block:"start"});}
