function addSaleLine(){const el=document.createElement("div");el.className="purchase-line sale-line";el.innerHTML='<div class="line-head"><strong>بند '+(++saleLineCount)+'</strong><button type="button" class="tiny secondary" data-remove-sale-line>حذف</button></div><label>المنتج<select data-field="product_id" required><option value="">اختر منتجًا</option>'+products.map(p=>'<option value="'+p.id+'">'+esc(p.name)+(p.code?" · "+esc(p.code):"")+'</option>').join("")+'</select></label><div class="form-grid"><label>الكمية<input data-field="quantity" type="number" min="0.001" step="0.001" value="1" required></label><label>سعر البيع للوحدة<input data-field="unit_price" type="number" min="0" step="0.01" value="0" required></label><label>خصم البند<input data-field="line_discount" type="number" min="0" step="0.01" value="0"></label><label>سعر الكتالوج<select data-field="price_type"><option value="auto">حسب العميل</option><option value="wholesale">جملة</option><option value="retail">قطاعي</option></select></label></div>';el.querySelectorAll("input,select").forEach(x=>x.addEventListener("input",()=>{if(x.dataset.field==="price_type"||x.dataset.field==="product_id"){const p=products.find(z=>z.id===el.querySelector('[data-field="product_id"]').value),c=customers.find(z=>z.id===$("saleCustomer").value),type=el.querySelector('[data-field="price_type"]').value==="auto"?(c?.customer_type||"retail"):el.querySelector('[data-field="price_type"]').value;if(p)el.querySelector('[data-field="unit_price"]').value=Number(type==="wholesale"?p.wholesale_price:p.retail_price||0);}updateSaleTotals();}));el.querySelector("[data-remove-sale-line]").addEventListener("click",()=>{el.remove();updateSaleTotals();});$("saleItems").appendChild(el);updateSaleTotals();}
function updateSaleTotals(){const lines=[...$("saleItems").querySelectorAll(".sale-line")];let gross=0,lineDiscounts=0;for(const l of lines){const q=Number(l.querySelector('[data-field="quantity"]').value||0),p=Number(l.querySelector('[data-field="unit_price"]').value||0),d=Number(l.querySelector('[data-field="line_discount"]').value||0);gross+=q*p;lineDiscounts+=d;}const invoiceDiscount=Number($("saleForm").elements.invoice_discount.value||0),total=gross-lineDiscounts-invoiceDiscount,paid=Number($("saleForm").elements.paid_amount.value||0);$("saleTotals").textContent="إجمالي البنود: "+money(gross)+" · خصم البنود: "+money(lineDiscounts)+" · خصم الفاتورة: "+money(invoiceDiscount)+" · الصافي: "+money(total)+" · المتبقي: "+money(total-paid);$("saleTotals").style.color=(lineDiscounts>gross||invoiceDiscount>gross-lineDiscounts||paid>total||[gross,lineDiscounts,invoiceDiscount,paid].some(n=>n<0))?"#a33":"";}
async function saveSale(e){e.preventDefault();if(!permission("sales.create"))return;const f=new FormData(e.currentTarget),lines=[...$("saleItems").querySelectorAll(".sale-line")].map(l=>({product_id:l.querySelector('[data-field="product_id"]').value,quantity:Number(l.querySelector('[data-field="quantity"]').value),unit_price:Number(l.querySelector('[data-field="unit_price"]').value),line_discount:Number(l.querySelector('[data-field="line_discount"]').value||0)}));if(!lines.length||lines.some(x=>!x.product_id||!Number.isFinite(x.quantity)||x.quantity<=0||!Number.isFinite(x.unit_price)||x.unit_price<0||!Number.isFinite(x.line_discount)||x.line_discount<0||x.line_discount>x.quantity*x.unit_price))return message("globalMessage","راجع المنتجات والكميات والأسعار والخصومات.");const gross=lines.reduce((a,x)=>a+x.quantity*x.unit_price,0),lineD=lines.reduce((a,x)=>a+x.line_discount,0),discount=Number(f.get("invoice_discount")||0),paid=Number(f.get("paid_amount")||0),total=gross-lineD-discount;if(discount<0||discount>gross-lineD||paid<0||paid>total)return message("globalMessage","الخصم أو المبلغ المحصل غير صحيح.");if(paid>0&&!permission("cash.create"))return message("globalMessage","ليس لديك صلاحية تسجيل تحصيل نقدي عند إنشاء الفاتورة. اترك المدفوع صفرًا.");message("globalMessage","جارٍ ترحيل فاتورة المبيعات والتحقق من المخزون...");const {data,error}=await client.rpc("post_sale",{p_business_id:activeBusinessId,p_invoice_no:String(f.get("invoice_no")).trim(),p_customer_id:f.get("customer_id")||null,p_invoice_date:f.get("invoice_date")||today(),p_items:lines,p_invoice_discount:discount,p_paid_amount:paid,p_notes:String(f.get("notes")||"").trim()||null});if(error)return fail(error);show("saleEditor",false);message("globalMessage","تم ترحيل فاتورة المبيعات بنجاح. رقم العملية: "+data);await Promise.all([loadProducts(),loadSalesModule()]);}
function renderSalesInvoices(){const q=$("salesSearch").value.trim().toLowerCase(),rows=salesInvoices.filter(x=>(x.invoice_no+" "+x.customer_name_snapshot).toLowerCase().includes(q));$("salesRows").innerHTML=rows.map(x=>'<tr><td>'+esc(x.invoice_no)+'</td><td>'+esc(x.invoice_date)+'</td><td>'+esc(x.customer_name_snapshot)+'</td><td>'+money(x.total)+'</td><td>'+money(x.paid_total)+'</td><td>'+money(x.due_total)+'</td><td><button class="tiny secondary" data-sale-details="'+x.id+'">تفاصيل</button> '+(Number(x.due_total)>0&&permission("payments.create")?'<button class="tiny" data-customer-pay="'+x.id+'">تحصيل</button>':"")+'</td></tr>').join("")||'<tr><td colspan="7">لا توجد فواتير مبيعات.</td></tr>';$("salesRows").querySelectorAll("[data-sale-details]").forEach(b=>b.addEventListener("click",()=>loadSaleDetails(salesInvoices.find(x=>x.id===b.dataset.saleDetails))));$("salesRows").querySelectorAll("[data-customer-pay]").forEach(b=>b.addEventListener("click",()=>openCustomerPayment(salesInvoices.find(x=>x.id===b.dataset.customerPay))));}
