function printSaleInvoice(){if(!currentSalePrint)return;const {invoice:i,items}=currentSalePrint;const w=window.open("","_blank","width=900,height=700");if(!w)return message("globalMessage","اسمح بالنوافذ المنبثقة لطباعة الفاتورة.");w.document.write('<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>فاتورة '+esc(i.invoice_no)+'</title><style>body{font-family:Tahoma,Arial;padding:28px;color:#172b3a}h1,h2{text-align:center}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #bbb;padding:10px;text-align:right}p{line-height:1.8}.totals{margin-top:20px;font-size:18px}</style><h1>'+esc(i.business_name_snapshot||"النسر للتجارة")+'</h1><h2>فاتورة مبيعات</h2><p>رقم الفاتورة: '+esc(i.invoice_no)+' · التاريخ: '+esc(i.invoice_date)+'</p><p>العميل: '+esc(i.customer_name_snapshot)+'</p><table><thead><tr><th>المنتج</th><th>الكمية</th><th>سعر الوحدة</th><th>الخصم</th><th>الإجمالي</th><th>الضمان</th></tr></thead><tbody>'+items.map(x=>'<tr><td>'+esc(x.product_name_snapshot)+'</td><td>'+x.quantity+'</td><td>'+money(x.unit_price)+'</td><td>'+money(x.line_discount)+'</td><td>'+money(x.line_total)+'</td><td>'+esc(x.warranty_snapshot||"—")+'</td></tr>').join("")+'</tbody></table><div class="totals"><p>الإجمالي: '+money(i.total)+'</p><p>المدفوع: '+money(i.paid_total)+' · المتبقي: '+money(i.due_total)+'</p></div><script>window.onload=()=>window.print()<\/script></html>');w.document.close();}
