function calculateReturn(){const inv=salesInvoices.find(x=>x.id===$("returnInvoice").value),items=[...$("returnItems").querySelectorAll(".return-line")].map(el=>{const source=returnInvoiceItems.find(x=>x.id===el.dataset.salesItem),quantity=Number(el.querySelector('[data-field="quantity"]').value||0),remaining=Number(source?.quantity||0)-Number(source?.returned_quantity||0);return {sales_item_id:el.dataset.salesItem,quantity,condition:el.querySelector('[data-field="condition"]').value,remaining,refund:source&&quantity>0?Math.round((Number(source.line_total)/Number(source.quantity))*quantity*100)/100:0};}).filter(x=>x.quantity>0);const total=Math.round(items.reduce((a,x)=>a+x.refund,0)*100)/100,cash=Number($("returnCashRefund").value||0),due=Number(inv?.due_total||0),minimumCash=Math.max(0,Math.round((total-due)*100)/100);return {inv,items,total,cash,due,minimumCash,credit:Math.max(0,total-cash)};}
