async function saveSalesReturn(e){e.preventDefault();if(!permission("sales.create"))return message("globalMessage","ليس لديك صلاحية تسجيل مرتجع.");const f=new FormData(e.currentTarget),x=calculateReturn();if(!x.inv)return message("globalMessage","اختر الفاتورة الأصلية.");if(!x.items.length)return message("globalMessage","حدد كمية مرتجعة واحدة على الأقل.");if(x.items.some(i=>!Number.isFinite(i.quantity)||i.quantity<=0||i.quantity>i.remaining))return message("globalMessage","راجع كميات المرتجع؛ لا يمكن تجاوز الكمية المتاحة.");if(!Number.isFinite(x.cash)||x.cash<x.minimumCash||x.cash>x.total)return message("globalMessage","قيمة الرد النقدي غير صحيحة. الحد الأدنى المطلوب "+money(x.minimumCash)+".");if(x.cash>0&&!permission("cash.withdraw"))return message("globalMessage","لا تملك صلاحية الصرف من الخزنة.");const payload={p_business_id:activeBusinessId,p_return_no:String(f.get("return_no")).trim(),p_sales_invoice_id:x.inv.id,p_items:x.items.map(i=>({sales_item_id:i.sales_item_id,quantity:i.quantity,condition:i.condition})),p_cash_refund:x.cash,p_return_date:f.get("return_date")||today(),p_notes:String(f.get("notes")||"").trim()||null};if(!payload.p_return_no)return message("globalMessage","أدخل رقم المرتجع.");message("globalMessage","جارٍ ترحيل المرتجع وتحديث المخزون والحساب والخزنة...");const {data,error}=await client.rpc("post_sales_return",payload);if(error)return fail(error);show("returnEditor",false);message("globalMessage","تم ترحيل المرتجع بنجاح. رقم العملية: "+data);await Promise.all([loadProducts(),loadSalesModule()]);}
